mapper.select:
select sq.id session_question_id,qa.id attempt_id,aa.id answer_id,sq.question_order,sq.presentation_snapshot::text presentation_snapshot,aa.answer_data::text answer_data,qa.status,cast(qa.presented_at as text) presented_at
from cm_session_question sq join cm_question_attempt qa on qa.session_question_id=sq.id and qa.attempt_no=1 join cm_attempt_answer aa on aa.attempt_id=qa.id
where sq.session_id=#{sessionId} and qa.user_id=#{userId} and sq.question_order=#{order}

select count(*) filter(where aa.answer_data->'value' is not null and aa.answer_data->'value' <> 'null'::jsonb) answered_count,count(*) total_count,
       min(sq.question_order) filter(where aa.answer_data->'value' is null or aa.answer_data->'value'='null'::jsonb) first_unanswered
from cm_session_question sq join cm_question_attempt qa on qa.session_question_id=sq.id and qa.attempt_no=1 join cm_attempt_answer aa on aa.attempt_id=qa.id where sq.session_id=#{sessionId} and qa.user_id=#{userId}
